using BotFramework.Discord.Commands;using BotFramework.Discord.Routing;using Games.Transfer.Application.Services;
namespace Games.Transfer.Discord;
public sealed class TransferDiscordHandler(ITransferService service):IDiscordMessageHandler{public bool CanHandle(DiscordMessageContext context)=>DiscordCommand.Is(context,"transfer");public async Task HandleAsync(DiscordMessageContext context){var p=DiscordCommand.Parts(context);var target=context.Message.MentionedUsers.FirstOrDefault();if(target is null||p.Length<2||!int.TryParse(p[^1], System.Globalization.CultureInfo.InvariantCulture, out var amount)||amount<=0){await DiscordCommand.ReplyAsync(context,"Использование: `transfer @user <amount>`");return;}var r=await service.TryTransferAsync(DiscordCommand.UserId(context),checked((long)target.Id),DiscordCommand.ScopeId(context),DiscordCommand.DisplayName(context),target.GlobalName??target.Username,amount,DiscordCommand.SourceId(context),context.CancellationToken);await DiscordCommand.ReplyResultAsync(context,r,"Transfer");}}
